#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    long long interactionCosts(int n,vector<vector<int>>& edges,vector<int>& group){
        vector<vector<int>>g(n);for(auto&e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
        const int LOG=18;vector<array<int,18>>up(n);vector<int>depth(n),tin(n),tout(n),order;
        order.reserve(n);vector<int>par(n,-1),it(n),stack(1,0);int timer=0;
        while(!stack.empty()){
            int u=stack.back();
            if(it[u]==0){tin[u]=timer++;order.push_back(u);up[u][0]=par[u]<0?u:par[u];
                for(int j=1;j<LOG;j++)up[u][j]=up[up[u][j-1]][j-1];}
            if(it[u]==(int)g[u].size()){tout[u]=timer;stack.pop_back();continue;}
            int v=g[u][it[u]++];if(v==par[u])continue;
            par[v]=u;depth[v]=depth[u]+1;stack.push_back(v);
        }
        auto ancestor=[&](int a,int b){return tin[a]<=tin[b]&&tout[b]<=tout[a];};
        auto lca=[&](int a,int b){
            if(ancestor(a,b))return a;if(ancestor(b,a))return b;
            for(int j=LOG-1;j>=0;j--)if(!ancestor(up[a][j],b))a=up[a][j];
            return up[a][0];
        };
        unordered_map<int,vector<int>>groups;
        for(int i=0;i<n;i++)groups[group[i]].push_back(i);
        long long ans=0;
        for(auto &entry:groups){
            vector<int>v=entry.second;int k=v.size();if(k<2)continue;
            sort(v.begin(),v.end(),[&](int a,int b){return tin[a]<tin[b];});
            int sz=v.size();for(int i=1;i<sz;i++)v.push_back(lca(v[i-1],v[i]));
            sort(v.begin(),v.end(),[&](int a,int b){return tin[a]<tin[b];});
            v.erase(unique(v.begin(),v.end()),v.end());
            vector<int>st;vector<long long>cnt(v.size(),0);
            for(int u:v){
                while(!st.empty()&&!ancestor(st.back(),u))st.pop_back();
                if(!st.empty()){
                    // Parent links of virtual tree are saved separately.
                }
                st.push_back(u);
            }
            vector<int>vp(v.size(),-1);st.clear();
            for(int i=0;i<(int)v.size();i++){
                while(!st.empty()&&!ancestor(v[st.back()],v[i]))st.pop_back();
                if(!st.empty())vp[i]=st.back();st.push_back(i);
                cnt[i]=(group[v[i]]==entry.first);
            }
            for(int i=(int)v.size()-1;i>0;i--){
                int p=vp[i];long long c=cnt[i];
                ans+=c*(k-c)*(depth[v[i]]-depth[v[p]]);
                cnt[p]+=c;
            }
        }
        return ans;
    }
};
